const $=(q,r=document)=>r.querySelector(q);const $$=(q,r=document)=>[...r.querySelectorAll(q)];
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',layers:'<path d="m12 3 10 6-10 6L2 9Z M2 13l10 6 10-6 M2 17l10 6 10-6"/>',cursor:'<path d="m5 3 14 10-7 1-3 7Z"/>',type:'<path d="M4 5V3h16v2 M12 3v18 M8 21h8"/>',plus:'<path d="M12 4v16M4 12h16"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20.5 13A9 9 0 0 1 11 3.5 9 9 0 1 0 20.5 13Z"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',handoff:'<path d="M13 3H5v18h14V11M13 3v8h6M13 3l6 8M8 16h6m-2-2 2 2-2 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.grid}</svg>`}
const topics=[['color','Color','A focused palette. A clear purpose.'],['typography','Typography','A voice you can see.'],['imagery','Imagery','Ideas, given a little dimension.'],['iconography','Iconography','Small details. Immediate meaning.'],['motion','Motion','Movement that makes sense.'],['voice','Voice & tone','A creative partner, in words.'],['foundations','Form & detail','The structure beneath the surface.'],['applications','In practice','One identity. Many possibilities.']];
const rules=(items)=>`<div class="rule-grid">${items.map(([a,b])=>`<div class="rule"><strong>${a}</strong><p>${b}</p></div>`).join('')}</div>`;
function cardVisual(id){return ({color:'<div class="color-stack"><i></i><i></i><i></i></div>',typography:'<div class="type-art">A<em>a</em></div>',imagery:'<img class="direction-landscape" src="assets/landscape.png" alt="">',iconography:`<div class="icons-art">${['folder','image','layers','cursor','globe','type'].map(icon).join('')}</div>`,motion:'<div class="motion-art"><i></i><i></i><i></i></div>',voice:'<div class="voice-art">A little<br>more you.</div>',foundations:'<div class="foundation-art"><i></i><i></i><i></i></div>',applications:'<div class="poster-mini">From a<br>thought.<br>To a thing.</div><div class="ui-mini">Your next great idea<div></div><div style="height:25px;width:70%"></div></div>'})[id]}
function cards(){return `<div class="direction-grid">${topics.map(([id,title,sub])=>`<a class="direction-card reveal card-${id==='typography'?'type':id==='iconography'?'icons':id}" href="#/${id}"><div class="card-head"><h3>${title}</h3><span class="card-plus" aria-hidden="true">+</span></div><div class="card-visual" aria-hidden="true">${cardVisual(id)}</div><div class="card-caption">${sub}</div></a>`).join('')}</div>`}
function home(){return `<section class="hero"><div class="hero-top"><span class="eyebrow">The DesignOS identity</span><span class="meta">An evolving creative system / v0.1</span></div><h1>Room for<br><span class="serif">ideas.</span></h1><div class="hero-intro"><p>A clear canvas. An open mind.<br>A brand built for what you’ll make next.</p><a class="text-link" href="#/direction">Explore the direction</a></div><div class="assembly-track"><div class="assembly" aria-label="Typography, imagery and interface fragments assemble as you scroll"><div class="piece piece-type"><small>SPACE TO EXPRESS</small><div class="big-aa">Aa</div><small>MANROPE / DM SANS</small></div><div class="piece piece-art"><div class="orb"></div></div><div class="piece piece-ui"><div class="mock-top"><b>DesignOS</b><span>Your workspace</span></div><div class="mock-title">What’s taking shape?</div><div class="mini-grid"><div><div class="mini-art"><div class="orb"></div></div><div class="tiny-label">A new perspective</div></div><div><div class="mini-art">Aa</div><div class="tiny-label">Your next direction</div></div></div><span class="cursor-tag">Made of possibilities</span></div></div></div></section><section class="section"><div class="section-head reveal"><div><span class="eyebrow">The idea behind the identity</span><h2>Structure for the work.<br>Space for the unexpected.</h2></div><p>DesignOS is a creative workspace for designs, images, artifacts and brands. Our identity gives the tools clarity—and the ideas room to breathe.</p></div><div class="principles"><article class="principle reveal"><span class="principle-icon">⌘</span><h3>Clear by nature</h3><p>Quiet surfaces. Obvious actions. The work always comes first.</p></article><article class="principle reveal"><span class="principle-icon">✳</span><h3>Open to possibility</h3><p>A restrained palette with an expressive, adaptable graphic language.</p></article><article class="principle reveal"><span class="principle-icon">↔</span><h3>Made to move forward</h3><p>Helpful words and purposeful motion turn a starting point into a next step.</p></article></div></section><section class="section" id="direction"><div class="section-head reveal"><div><span class="eyebrow">The building blocks</span><h2>Different parts.<br>One point of view.</h2></div><p>Explore the visual language.<br>Try it, understand it, make it yours.</p></div>${cards()}</section><section class="statement"><span class="meta">The expression</span><h2 class="reveal">Some things need<br>more <em>imagination.</em><br>Others, less noise.</h2><p>The brand can be expressive. The workspace stays focused. A shared foundation brings both together.</p></section><section class="section"><div class="section-head reveal"><div><span class="eyebrow">Built for real work</span><h2>A little brand.<br>A lot of possibility.</h2></div><a class="text-link" href="#/applications">See it in practice</a></div>${productDemo()}</section><div class="resources-band"><h2>Good things are made to be used.</h2><a class="pill-button" href="#/resources">Get the toolkit</a></div>`}
function intro(id,title,lead){return `<section class="page-intro"><div class="breadcrumb"><a href="#/direction">Direction</a><span>/</span><span>${title}</span></div><div class="page-kicker"><span class="eyebrow">The DesignOS identity</span><span class="meta">Draft direction / v0.1</span></div><h1>${title}</h1><p class="lead">${lead}</p></section>`}
function section(title,note,body,cls=''){return `<section class="content-section ${cls}"><h2>${title}</h2>${note?`<p class="section-note">${note}</p>`:''}${body}</section>`}
function next(id){let i=topics.findIndex(t=>t[0]===id),n=topics[(i+1)%topics.length];return `<div class="next-page"><span class="meta">Keep exploring</span><a href="#/${n[0]}">${n[1]}</a></div>`}
function productDemo(){return `<div class="product-demo"><aside class="product-side"><b>DesignOS</b>${['Home','Projects','Prompts','Artifacts','Assets','Brands','Handoff'].map((s,i)=>`<span class="${i===1?'selected':''}">${s}</span>`).join('')}</aside><div class="product-main"><div class="product-toolbar"><span class="meta">Example workspace</span><button class="pill-button demo-create">New project</button></div><h3>Your next great idea starts here.</h3><p>A place for your projects. Space for your process.</p><div class="product-cards"><div class="product-card"><div class="product-card-art"><div class="orb"></div></div>Brand exploration<div class="tiny-label">Brand · In progress</div></div><div class="product-card"><div class="product-card-art">New<br>perspectives.</div>Editorial website<div class="tiny-label">Design · Draft</div></div><div class="product-card"><div class="product-card-art">✳</div>Campaign assets<div class="tiny-label">Images · Ready</div></div></div></div></div>`}
const palette=[['Canvas','#F8F9F6','Primary light background'],['Ink','#172724','Text and dark surfaces'],['Deep teal','#006B60','Light-theme actions'],['Mint','#C2F4D7','Brand expression'],['White','#FFFFFF','Elevated light surfaces']];
function lum(h){return [1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((s,v,i)=>s+v*[.2126,.7152,.0722][i],0)}function ratio(a,b){let x=lum(a),y=lum(b);return ((Math.max(x,y)+.05)/(Math.min(x,y)+.05)).toFixed(2)}
function colors(){return intro('color','Color','Mostly quiet. Occasionally unmistakable. A focused palette that gives your work the spotlight.')+section('Five colors. Plenty of room.','Click a swatch to copy its value.',`<div class="palette">${palette.map(([n,h,u])=>`<button class="swatch" data-copy="${h}" aria-label="Copy ${n} ${h}"><span class="swatch-color" style="background:${h}"></span><span class="swatch-label">${n}<small>${h}</small><small>${u}</small></span></button>`).join('')}</div>`)+section('Contrast is part of the identity.','These approved text pairs are calculated using relative luminance. Color alone never communicates a status.',`<div class="contrast-grid">${[['#F8F9F6','#172724','Ink on Canvas'],['#006B60','#FFFFFF','White on Deep teal'],['#C2F4D7','#172724','Ink on Mint']].map(([bg,fg,n])=>`<div class="contrast-tile" style="background:${bg};color:${fg}"><span class="contrast-aa">Aa</span><p>${n}<br>${ratio(bg,fg)}:1 · AA normal text</p></div>`).join('')}</div>${rules([['Keep surfaces neutral','Use Canvas and White for most of the interface. Teal identifies meaningful actions.'],['Mint needs dark text','Use Ink on Mint. White on Mint is not an approved text pairing.'],['Gradients belong to artwork','Use teal-to-mint tonal gradients in imagery. Keep text and primary controls on solid surfaces.']])}`)+section('Two modes. Equal clarity.','Light and dark themes have their own semantic tokens. Use the sun or moon in the header to explore both.',`<table class="token-table"><thead><tr><th>Role</th><th>Light</th><th>Dark</th></tr></thead><tbody>${[['Background','#F8F9F6','#121B19'],['Surface','#FFFFFF','#1C2824'],['Primary text','#172724','#F3F6F1'],['Secondary text','#586661','#B0BEB5'],['Action / focus','#006B60','#9DE4C3'],['Button label','#F8F9F6','#172724'],['Decorative divider','#D8DFDA','#405047']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="draft-note">Semantic support: success “Saved”, warning “Review needed”, error “Couldn’t save”, info “Draft”. Always pair a status color with an icon or label. Low-contrast dividers are decorative; interactive fields use a stronger boundary or clear fill.</p>`)+next('color')}
function typography(){return intro('typography','Typography','Confident enough to say less. Flexible enough to say it your way.')+section('Manrope makes the statement.','A geometric display face with a human rhythm. Try your own words.',`<div class="visual-stage"><div class="controls"><label>Your words <input id="type-input" type="text" value="Make room for ideas." maxlength="100"></label><label>Size <input id="type-size" type="range" min="28" max="130" value="80"><output id="type-size-label">80 px</output></label><label>Weight <select id="type-weight"><option value="400">Regular</option><option value="550" selected>Medium</option><option value="700">Bold</option></select></label></div><div class="specimen" id="specimen" style="font-size:80px">Make room for ideas.</div><span class="meta">ABCDEFGHIJKLMNOPQRSTUVWXYZ / 0123456789</span></div>`)+section('One family for expression. One for clarity.','Manrope leads brand moments. DM Sans keeps the product comfortable. IBM Plex Mono handles tokens and code.',`<div class="type-row"><span style="font-size:64px">Room for ideas.</span><small>Manrope · 64 / 68 · 600</small></div><div class="type-row"><span style="font-size:40px">Your creative workspace</span><small>Manrope · 40 / 46 · 600</small></div><div class="type-row"><span style="font-size:28px">A new perspective</span><small>Manrope · 28 / 34 · 550</small></div><div class="type-row"><span style="font:18px var(--body)">Start with a thought. See where it goes.</span><small>DM Sans · 18 / 28 · 400</small></div><div class="type-row"><span style="font:16px var(--body)">Create your first project.</span><small>DM Sans · 16 / 24 · 400</small></div><div class="type-row"><span style="font:14px var(--body)">Project settings</span><small>DM Sans · 14 / 20 · 500</small></div>${rules([['Big type, small doses','Use tight tracking for short display headings. Restore normal spacing for body and UI text.'],['Comfort before density','Use 16 px for reading and 14 px for controls. Reserve 12 px for secondary metadata.'],['A dependable fallback','Manrope and DM Sans fall back to Arial and sans-serif. Mono falls back to monospace.']])}`)+section('Open fonts. Clear roles.','Font files are served through Google Fonts in this exploration.',`<p>Manrope, DM Sans and IBM Plex Mono are published under the SIL Open Font License. Keep the relevant license with any self-hosted distribution.</p><div class="treatment-tabs"><a class="pill-button secondary" href="https://fonts.google.com/specimen/Manrope" target="_blank" rel="noopener">Manrope</a><a class="pill-button secondary" href="https://fonts.google.com/specimen/DM+Sans" target="_blank" rel="noopener">DM Sans</a><a class="pill-button secondary" href="https://fonts.google.com/specimen/IBM+Plex+Mono" target="_blank" rel="noopener">IBM Plex Mono</a></div>`)+next('typography')}
function imagery(){return intro('imagery','Imagery','Give an idea a shape. Then give it a little space.')+section('One form. Different expressions.','Our starting vocabulary: rounded forms, layered planes and tonal teal. Change the treatment to see the system adapt.',`<div class="treatment-tabs" role="group" aria-label="Imagery treatment"><button data-treatment="dimensional" aria-pressed="true">Dimensional</button><button data-treatment="outline" aria-pressed="false">Outline</button><button data-treatment="flat" aria-pressed="false">Flat</button></div><div class="imagery-stage dimensional"><div class="orb"></div></div>${rules([['Recognizable materials','Use matte surfaces, subtle depth and a single directional light. Keep the palette tonal.'],['A point of view','A single clear subject, generous negative space and purposeful crops. Let shape carry the idea.'],['Product work stays real','Use realistic project names and clear interface captures. Label concepts and illustrative examples.']])}`)+section('Show the thought, not the cliché.','Use visual transformations, arrangements and product artifacts to express creativity.',`<div class="do-dont"><div class="example"><h3>USE</h3><div class="sample">A form becoming<br>a new possibility.</div><p>One material, one subject, a meaningful transformation.</p></div><div class="example bad"><h3>AVOID</h3><div class="sample">The generic<br>AI universe.</div><p>Unrelated neon planets, robot brains, rainbow clouds and arbitrary technology imagery.</p></div></div>`)+section('An asset you can build with.','The orbital form is original SVG artwork. It is a graphic device, not the final logo.',`<a class="pill-button" href="assets/orbit.svg" download>Download orbital artwork</a><p class="draft-note">Photography direction: show creative work in context—hands arranging, making and reviewing. Natural directional light, honest color and uncluttered compositions. Photography is optional; no stock-photo filler is required.</p>`)+next('imagery')}
const iconNames=['grid','folder','image','layers','cursor','type','plus','search','download','check','close','globe','spark','handoff','settings','heart','chat','clock'];
function iconography(){return intro('iconography','Iconography','A small vocabulary for a much bigger world of work.')+section('Simple shapes. Familiar meaning.','24 px construction grid. 1.75 px strokes. Rounded joins and caps. Click any icon to download its SVG.',`<label class="controls">Find an icon <input class="search" id="icon-search" placeholder="Try folder, image, layers…" type="search"></label><div class="icon-grid">${iconNames.map(n=>`<button class="icon-cell" data-icon="${n}" aria-label="Download ${n} icon">${icon(n)}<span>${n}</span></button>`).join('')}</div><p class="empty-result" hidden>No matching icons. Try “folder” or “image”.</p>${rules([['One stroke language','Keep UI icons at 1.75 px on a 24 px grid. Use 16, 20 or 24 px outputs with optical checks.'],['Meaning before decoration','Pair unfamiliar actions with a text label. Icon-only controls require an accessible name.'],['Use the quietest color','Use the same semantic text tokens as surrounding controls. Save teal for selected and active states.']])}`)+next('iconography')}
function motion(){return intro('motion','Motion','A little movement. A clearer next step.')+section('Things find their place.','Our signature gesture moves scattered possibilities into a clear composition. Product interactions use the same ease, with less travel.',`<div class="visual-stage"><div class="controls"><label>Duration <select id="motion-duration"><option value="180">180 ms · feedback</option><option value="280">280 ms · transition</option><option value="800" selected>800 ms · expression</option></select></label><button class="pill-button" id="replay">Replay motion</button></div><div class="demo-lane"><div class="demo-ball"></div></div><code>cubic-bezier(0.22, 1, 0.36, 1)</code></div>`)+section('A rhythm for every context.','Responsive in the workspace. More expressive on the brand stage.',`<div class="motion-times"><div class="motion-time"><b>180 ms</b>Feedback<p>Buttons, toggles and hover states.</p></div><div class="motion-time"><b>280 ms</b>Transition<p>Panels, menus and content changes.</p></div><div class="motion-time"><b>800 ms</b>Expression<p>Brand sequences and large compositions.</p></div></div>${rules([['Move with a reason','Show where something came from, what changed and where attention should go.'],['Keep people in control','Natural scroll, replayable demos and no essential information hidden behind animation.'],['Respect reduced motion','Honor prefers-reduced-motion. Remove parallax and travel; show the resolved state immediately.']])}`)+section('Brand motion is not loading feedback.','A real generation task needs an honest status and a way to recover.',`<div class="do-dont"><div class="example"><h3>PRODUCT FEEDBACK</h3><div class="sample">Creating your image…</div><p>Indeterminate progress with a visible cancel option when supported. Never invent a completion percentage.</p></div><div class="example"><h3>BRAND EXPRESSION</h3><div class="sample">Ideas coming together.</div><p>A short composition. No status claims. A distinct moment away from the task.</p></div></div>`)+next('motion')}
function voice(){return intro('voice','Voice & tone','A thoughtful creative partner. Clear about the work. Open to what’s possible.')+section('Say the useful thing.','Short sentences. Specific actions. Warmth without a performance.',`<div class="visual-stage"><div class="voice-art" style="max-width:800px;font-size:clamp(45px,6vw,85px)">Your idea.<br>A place to begin.</div></div>${rules([['Clear','Name the action and the result. “Create project” is easier to understand than “Unlock your potential”.'],['Encouraging','Give a next step without judging the work. Treat exploration as part of the process.'],['Honest','Describe what happened. Acknowledge limits. Never claim a draft is a finished result.']])}`)+section('Same personality. Different moments.','Adjust the tone to the user’s situation.',`<div class="do-dont"><div class="example"><h3>EMPTY STATE</h3><div class="sample">A little space<br>for your next idea.</div><p>Create your first project to get started.</p></div><div class="example"><h3>ERROR</h3><div class="sample">We couldn’t<br>save your changes.</div><p>Your draft is still here. Try saving again.</p></div><div class="example"><h3>SUCCESS</h3><div class="sample">Your brand kit<br>is ready.</div><p>Review the colors and type before sharing.</p></div><div class="example bad"><h3>AVOID</h3><div class="sample">Oopsie! Our creative<br>elves got confused!</div><p>Humor shouldn’t get between someone and a solution.</p></div></div>`)+next('voice')}
function foundations(){return intro('foundations','Form & detail','The quiet decisions that make everything feel like it belongs.')+section('Rounded with a reason.','Use radius to express hierarchy. Small controls are precise. Large containers have more room.',`<div class="radii">${[[6,'Controls'],[10,'Product cards'],[16,'Brand panels'],[999,'Chips only']].map(([n,t])=>`<div><div class="radius-sample" style="border-radius:${n}px">${n===999?'Full':n+' px'}</div><p>${t}</p></div>`).join('')}</div>${rules([['Nested curves','Subtract the container padding from the outer radius when a nested panel needs to follow its curve.'],['Avoid the pill habit','Reserve full rounding for chips, compact toggles and tags. Standard product buttons use 6 px.'],['Space has a rhythm','Use a 4 px base: 4, 8, 12, 16, 24, 32, 48, 64. Prefer proximity over extra borders.']])}`)+section('Different jobs. Different strokes.','Dividers organize. Controls communicate affordance. Icons keep a consistent optical weight.',`<div class="stroke-demo"><span>1 px / decorative divider</span><span>1.75 px / icon stroke at 24 px</span><span>2 px / focus ring minimum thickness (3 px on this site)</span></div><p class="draft-note">Use subtle borders for non-interactive groups. Input boundaries and essential graphical controls need 3:1 contrast against their immediate background. Focus must remain visible on both light and dark surfaces.</p>`)+section('Comfortable density. Clear hierarchy.','Dashboard examples use stable alignment, readable labels and a single dominant action.',productDemo())+section('An empty state should open a door.','One explanation. One useful action. No decorative metrics.',`<div class="empty-state">${icon('folder')}<h3>A little space for your next idea.</h3><p>Create a project to keep your designs, images and brand work together.</p><button class="pill-button demo-create">Create a project</button></div>`)+next('foundations')}
function applications(){return intro('applications','In practice','A single point of view, from the first impression to the everyday workspace.')+section('The product stays focused.','Illustrative dashboard concept based on the supplied product. Content and project actions here demonstrate the identity.',productDemo())+section('The launch can be expressive.','The same palette and type, turned up for a brand moment.',`<div class="application-grid"><div class="poster"><span class="meta">DesignOS / A creative workspace</span><h3>From a thought.<br>To a thing.</h3><div class="orb"></div><span class="meta">Make room for ideas.</span></div><div class="poster dark"><span class="meta">A new perspective</span><h3>Less noise.<br>More<br>possibility.</h3><span style="font:100px Georgia">✳</span><span class="meta">Your ideas have a place here.</span></div></div>`)+section('A slide needs room to breathe.','A presentation title uses the same hierarchy, spacing and tonal artwork.',`<div class="visual-stage" style="min-height:340px;display:flex;flex-direction:column;justify-content:space-between"><span class="meta">DesignOS / Brand direction</span><div style="font:600 clamp(40px,6vw,85px)/1 var(--display);letter-spacing:-.06em;margin:40px 0">A clear canvas.<br>An open mind.</div><span class="meta">Identity exploration · 2026</span></div>`)+section('Designed to travel.','Three application assets are available as editable SVGs.',`<a class="pill-button" href="#/resources">Explore the resources</a>`)+next('applications')}
function resources(){return intro('resources','The toolkit','Take the useful parts with you. A small, practical foundation for designers, developers and AI.')+section('Ready to work with.','All files describe this draft direction. The name and logo remain provisional.',`<div class="resource-list">${[['Landscape study','Original AI-generated teal landscape for covers and brand compositions.','assets/landscape.png','PNG'],['Gradient field','Original scalable tonal light study.','assets/gradient-field.svg','SVG'],['Brand tokens','Light and dark colors, typography, spacing, radii and motion.','assets/tokens.json','JSON'],['Brand guidance for AI','A concise specification to use when creating new product screens and brand assets.','assets/brand-guidance.md','MARKDOWN'],['Orbital artwork','Original scalable artwork for brand compositions.','assets/orbit.svg','SVG'],['Placeholder mark','A temporary construction mark, explicitly not the final logo.','assets/placeholder-mark.svg','SVG'],['Launch poster','A square application of the proposed identity.','assets/launch-poster.svg','SVG'],['Presentation title','A widescreen example for decks and announcements.','assets/presentation.svg','SVG'],['Product concept','A dashboard application with neutral surfaces and focused teal actions.','assets/product-concept.svg','SVG'],['Icon collection','18 original outline icons with consistent 24 px construction.','assets/icons.svg','SVG SPRITE']].map(([t,d,f,fmt])=>`<article class="resource-item"><span class="meta">${fmt} / Draft v0.1</span><h2>${t}</h2><p>${d}</p><a class="pill-button secondary" href="${f}" download>Download ${fmt}</a></article>`).join('')}</div>`)+section('What is still open?','This is a usable proposal, ready for iteration.',rules([['Name and logo','DesignOS and the four-part mark are placeholders. Replace both before a public brand rollout.'],['Product validation','Review the tokens against real screens, long labels, error states and actual generation flows.'],['The next iteration','Refine the visual direction after reviewing this site. Keep the rules and examples in sync.']]))+section('Reference notes','Presentation inspired by the visual navigation of Wise and the compositional motion of Dropbox. Identity artwork and implementation are original.',`<div class="treatment-tabs"><a class="pill-button secondary" href="https://wise.design/direction" target="_blank" rel="noopener">Wise Direction</a><a class="pill-button secondary" href="https://brand.dropbox.com/" target="_blank" rel="noopener">Dropbox Brand</a><a class="pill-button secondary" href="https://github.com/rampstackco/claude-skills/tree/main/skills/brand-identity" target="_blank" rel="noopener">Brand identity skill</a></div>`)}
function direction(){return intro('direction','The direction','A collection of parts. A coherent way of seeing. Explore the identity one element at a time.')+`<section class="section" style="padding-top:10px">${cards()}</section>`+section('An evolving identity.','A focused starting point for an AI creative workspace.',rules([['The foundation','Monochrome first, deep teal for actions, mint for expression.'],['The distinction','Expressive presentation. Dependable product interfaces. Shared visual DNA.'],['The open decisions','Name and logo remain placeholders. The visual language is a proposal for review.']]))}
const pages={home,direction,color:colors,typography,imagery,iconography,motion,voice,foundations,applications,resources};
let observer,scrollHandler;
function toast(s){$('.toast').textContent=s;$('.toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2300)}
function updateTheme(){const dark=document.documentElement.dataset.theme==='dark';$('.theme').innerHTML=icon(dark?'sun':'moon');$('.theme').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('.theme').title=dark?'Switch to light mode':'Switch to dark mode'}
$('.theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('brand-theme',theme)}catch(e){}updateTheme()};updateTheme();
function downloadText(text,name,type='image/svg+xml'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function bind(){observer?.disconnect();observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>observer.observe(e));
$$('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast(`${b.dataset.copy} copied`)}catch(e){toast(`Color value: ${b.dataset.copy}`)}});
if($('#type-input')){$('#type-input').oninput=e=>$('#specimen').textContent=e.target.value||'Make room for ideas.';$('#type-size').oninput=e=>{$('#specimen').style.fontSize=e.target.value+'px';$('#type-size-label').value=e.target.value+' px'};$('#type-weight').onchange=e=>$('#specimen').style.fontWeight=e.target.value}
$$('[data-treatment]').forEach(b=>b.onclick=()=>{$('.imagery-stage').className='imagery-stage '+b.dataset.treatment;$$('[data-treatment]').forEach(x=>x.setAttribute('aria-pressed',x===b))});
$$('[data-icon]').forEach(b=>b.onclick=()=>{downloadText(icon(b.dataset.icon).replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" ').replace('stroke="currentColor"','stroke="#172724"'),b.dataset.icon+'.svg');toast(`${b.dataset.icon}.svg downloaded`)});
if($('#icon-search'))$('#icon-search').oninput=e=>{let count=0;$$('[data-icon]').forEach(b=>{b.hidden=!b.dataset.icon.includes(e.target.value.trim().toLowerCase());if(!b.hidden)count++});$('.empty-result').hidden=count>0};
if($('#replay'))$('#replay').onclick=()=>{const lane=$('.demo-lane');lane.classList.remove('play');lane.style.setProperty('--duration',$('#motion-duration').value+'ms');void lane.offsetWidth;lane.classList.add('play')};
$$('.demo-create').forEach(b=>b.onclick=()=>{const area=b.closest('.product-demo')?.querySelector('.product-cards');if(area){const c=document.createElement('div');c.className='product-card';c.innerHTML='<div class="product-card-art">'+icon('folder')+'</div>Untitled project<div class="tiny-label">Draft · Just created</div>';area.prepend(c);if(area.children.length>3)area.lastElementChild.remove();toast('Example project created. This is a brand preview.')}else{b.closest('.empty-state').innerHTML=icon('check')+'<h3>Your project has a place.</h3><p>Untitled project · Draft</p><span class="meta">Illustrative product state</span>'}});
if(scrollHandler)removeEventListener('scroll',scrollHandler);const assembly=$('.assembly');if(assembly){scrollHandler=()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const track=$('.assembly-track'),rect=track.getBoundingClientRect(),p=Math.max(0,Math.min(1,(110-rect.top)/(track.offsetHeight-assembly.offsetHeight-110)));$$('.piece',assembly).forEach((el,i)=>{const r=[-12,12,-7][i]*(1-p),x=[-25,0,25][i]*(1-p),y=[15,45,-15][i]*(1-p);el.style.transform=`translate(${x}px,${y}px) rotate(${r}deg)`;el.style.boxShadow=`0 ${20*(1-p)}px ${40*(1-p)}px #00000012`});assembly.style.setProperty('--assembly-progress',p)};addEventListener('scroll',scrollHandler,{passive:true});scrollHandler()}}
function render(){const id=(location.hash.replace(/^#\/?/,'').split('?')[0]||'home');const page=pages[id]||home;$('#main').innerHTML=page();document.title=`${id==='home'?'Room for ideas':topics.find(t=>t[0]===id)?.[1]||id.charAt(0).toUpperCase()+id.slice(1)} — DesignOS Brand`;$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(id==='home'?'home':id==='resources'?'resources':'direction');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});scrollTo({top:0,left:0,behavior:"instant"});bind()}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true})});render();
